    /** Actions in the order of MobAnims.StarCurator. */
    public static final AnimationDefinition[] ACTIONS = {STAFF, VOLLEY, WELL, STARFALL, ORBIT, LANCE, PAGESTORM, CONSTELLATION, INVERT, BLINK, STARLANCE, ROAR, STAGGER};

    private final ModelPart head;
    private final KeyframeAnimation idle;
    private final KeyframeAnimation walk;
    private final KeyframeAnimation[] actions;

    public StarCuratorModel(ModelPart root) {
        super(root, RenderTypes::entityCutout);
        this.head = root.createPartLookup().apply("head");
        this.idle = IDLE.bake(root);
        this.walk = WALK.bake(root);
        this.actions = new KeyframeAnimation[ACTIONS.length];
        for (int i = 0; i < ACTIONS.length; i++) {
            this.actions[i] = ACTIONS[i].bake(root);
        }
    }

